@dataclass
class P:
    sport: str
    category: str
    brand: str
    name: str
    sku: str
    mrp: int
    price: int
    qty: int
    kg: float
    item: str          # illustration drawer
    role: str          # kitRole
    sub: str           # subCategory
    skill: str         # beginner | intermediate | advanced | all_levels
    use: str           # useCase
    desc: str
    features: list[str] = field(default_factory=list)
    material: str | None = None
    age: str = "adult"
    sizes: str | None = None
    extra: dict[str, str] = field(default_factory=dict)
    suitable: str | None = None


